<?php get_header(); ?><main id="main-content" class="container page-wrap single-video-wrap">
<?php while(have_posts()):the_post(); $mode=get_post_meta(get_the_ID(),'_javteen_playback_mode',true); $url=get_post_meta(get_the_ID(),'_javteen_video_url',true); $ext=strtolower(pathinfo((string)wp_parse_url($url,PHP_URL_PATH),PATHINFO_EXTENSION)); $direct=in_array($ext,array('mp4','webm','ogg','m3u8'),true); ?>
<article <?php post_class('video-detail'); ?>><div class="video-player">
<?php if($url && 'direct'===$mode && $direct): $mime='webm'===$ext?'video/webm':('ogg'===$ext?'video/ogg':('m3u8'===$ext?'application/vnd.apple.mpegurl':'video/mp4')); ?>
<video controls playsinline preload="metadata" poster="<?php echo esc_url(get_the_post_thumbnail_url(get_the_ID(),'large') ?: ''); ?>"><source src="<?php echo esc_url($url); ?>" type="<?php echo esc_attr($mime); ?>"><?php esc_html_e('Your browser does not support HTML video.','javteen'); ?></video>
<?php elseif($url && 'embed'===$mode): $embed=wp_oembed_get($url,array('width'=>1200)); if($embed){echo wp_kses($embed,array('iframe'=>array('src'=>true,'width'=>true,'height'=>true,'frameborder'=>true,'allow'=>true,'allowfullscreen'=>true,'title'=>true,'loading'=>true,'referrerpolicy'=>true),'div'=>array('class'=>true),'blockquote'=>array('class'=>true,'cite'=>true),'a'=>array('href'=>true,'title'=>true),'script'=>array('src'=>true,'async'=>true,'charset'=>true)));}else{echo '<p class="player-message">'.esc_html__('This URL could not be embedded by WordPress. Check that the provider supports oEmbed.','javteen').'</p>';} ?>
<?php else: ?><div class="player-placeholder"><span class="play-symbol">▶</span><p><?php esc_html_e('Video source not configured yet.','javteen'); ?></p></div><?php endif; ?></div>
<div class="video-detail-heading"><div><span class="eyebrow"><?php esc_html_e('NOW PLAYING','javteen'); ?></span><h1><?php the_title(); ?></h1><p class="meta"><?php echo esc_html(get_the_date()); ?></p></div></div><div class="video-description"><?php the_content(); ?></div>
<?php $terms=get_the_terms(get_the_ID(),'video_category'); if($terms && !is_wp_error($terms)): ?><div class="tag-list"><?php foreach($terms as $term): ?><a href="<?php echo esc_url(get_term_link($term)); ?>"><?php echo esc_html($term->name); ?></a><?php endforeach; ?></div><?php endif; ?>
</article><section class="related-section"><div class="section-heading"><h2><?php esc_html_e('More to explore','javteen'); ?></h2></div><div class="video-grid"><?php $related=new WP_Query(array('post_type'=>'video','post_status'=>'publish','posts_per_page'=>4,'post__not_in'=>array(get_the_ID()),'no_found_rows'=>true)); while($related->have_posts()):$related->the_post();get_template_part('template-parts/video-card');endwhile;wp_reset_postdata(); ?></div></section>
<?php endwhile; ?></main><?php get_footer(); ?>